#include <stdio.h>
int main(void) {
    double a, b, c, total, average;
    printf("Enter three marks: ");
    if (scanf("%lf %lf %lf", &a, &b, &c) != 3) {
        printf("Invalid input\n");
        return 1;
    }
    total = a + b + c;
    average = total / 3.0;
    printf("Total: %.2f\nAverage: %.2f\n", total, average);
    if (average >= 10.0) printf("Pass\n");
    else printf("Needs practice\n");
    return 0;
}
